package typeoracle

func Compact[S ~[]E, E comparable](value S) S { return value }
func CloneMap[M ~map[K]V, K comparable, V any](value M) M { return value }
type Key struct{ ID int; _ int }
func (key Key) Use(n int) {}
type OtherKey struct{ ID string }
func (key OtherKey) Use(n int) {}
type Item struct{ Field int }
func (item *Item) Use(n int) {}
type Other struct{ OtherField int }
func (item *Other) Use(n int) {}
type Keys []Key
type Lookup map[Key]*Item
func Navigate(values Keys, lookup Lookup) {
 checked := Compact(values)
 key := checked[0]
 key.Use(1)
 copied := CloneMap(lookup)
 copied[key].Use(2)
}

